    {
      "card_ids": ["C08"],
      "claim": "The isopropyl amide analogue (Morgan 0.7018) also showed B/P > 0.3 after ip dosing in mice, confirming that amide substituent variation at this position preserves brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "The same isopropyl amide analogue reached significant brain levels after oral administration in mice, demonstrating CNS access after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "An ester analogue with the same amino-thienopyridazinone/chlorophenyl core (Morgan 0.6167) showed B/P > 0.3 after ip dosing, supporting scaffold-level brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Another ester analogue (Morgan 0.6167) also showed B/P > 0.3 after ip dosing, reinforcing the pattern of CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The dimethylamide analogue (Morgan 0.6066) showed B/P > 0.3 after ip dosing, further supporting that this compound family penetrates the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Multiple close analogues sharing the amino-thienopyridazinone core and 4-chlorophenyl group show B/P > 0.3 after ip dosing and significant brain levels after oral dosing in mice, directly supporting meaningful CNS access for the query. Low-similarity negative records are structurally too distant to override this evidence.",
  "evidence_gaps": [
    "Direct pharmacokinetic measurement for the exact query molecule is absent; inference relies on close analogues.",
    "Reported B/P ratios are total brain/plasma exposures, not unbound brain concentrations; efflux liability was not directly quantified.",
    "Most evidence is from mouse ip studies; only one close analogue was tested orally.",
    "Low-similarity fail compounds (C07, C01) were not used as primary evidence due to structural divergence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

